) -> SIMDFloat16.Vector {
    HighwayReference.Nothrow.approximateReciprocalSquareRootWhereF16(
        mask.raw,
        HighwayReference.Nothrow.repeatingF16(Float16(bitPattern: 26).bitPattern)
    )
}
